document.addEventListener("DOMContentLoaded",()=>{let t={word:80,web:95,graphic:70,ppt:60};function r(e){var t=Number(e.min)||0,r=Number(e.max)||100,r=((Number(e.value)||0)-t)/(r-t)*100;e.style.setProperty("--val",r+"%"),e.style.background=`linear-gradient(to right, #000 ${r}%, #e0e0e0 ${r}%)`}document.querySelectorAll('.skill input[type="range"]').forEach(e=>{e.id&&void 0!==t[e.id]&&(e.value=t[e.id]),r(e),e.addEventListener("input",()=>r(e))})});